-- 📚 꼭집 주거 사전 — 갱신계약 소득초과 할증 · 공통 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 🔵 2026-11-09(조사 「사전 5차 후보 둘」 2-ⓓ · 우편함 「코드·운영 — 📚 사전 SQL 새 둘 + 개정 둘 …」 1) — 갈래 셈(anns·by_std·ex = 종전 값 그대로)에
--   문장 셈을 더한다: reverify 원문화가 옛 「갱신 할증」 요약 행을 원문 문단 행(「임대조건」 등)으로 바꾸면 할증 문장이 큰 행 안으로 들어가 갈래 셈이 준다(국민임대 61 → 56).
--   sent = 정책 문장에 「할증」이 「갱신」·「재계약」과 120자 안에(최초 계약·완화 모집 할증만 적은 문장은 거른다) · any = 갈래 ∪ 문장 · sent_not_cls = 문장에는 있고 「갱신 할증」 갈래 행은 없는 공고.
-- 확인 2026-11-09 · 실행 약 4초(관리 API 왕복) · 결과:
-- {"anns": 137, "by_std": {"국민임대": 56, "매입임대": 31, "전세임대": 4, "통합공공임대": 11, "행복주택": 29, "행복주택(신혼희망)": 6}, "ex": ["21442_1_제주특별자치도_서귀포시", "20857_1_제주특별자치도_서귀포시", "20652_1_서울특별시_영등포구", "2015122300020993"], "sent": 235, "sent_by_std": {"행복주택(신혼희망)": 11, "SH 고유": 6, "영구임대": 11, "국민임대": 97, "행복주택": 45, "매입임대": 50, "통합공공임대": 11, "전세임대": 4}, "any": 254, "any_by_std": {"행복주택(신혼희망)": 11, "SH 고유": 6, "영구임대": 11, "매입임대": 50, "국민임대": 115, "행복주택": 46, "통합공공임대": 11, "전세임대": 4}, "sent_not_cls": 117, "cls_not_sent": 19}
-- (종전 2026-10-13 · 실행 3.0초 · 갈래 셈만:)
-- {"anns": 117, "by_std": {"국민임대": 61, "매입임대": 28, "전세임대": 4, "통합공공임대": 4, "행복주택": 18, "행복주택(신혼희망)": 2}, "ex": ["20652_1_서울특별시_영등포구", "2015122300020871", "2015122300020870", "2015122300020855"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026),f as(select announcement_id,std,bool_or(cls='갱신 할증')c,bool_or(t~'(갱신|재계약).{0,120}할증|할증.{0,120}(갱신|재계약)')w from y group by 1,2)select json_build_object('anns',(select count(distinct announcement_id) from y where '갱신 할증'=cls),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where cls='갱신 할증' group by 1)q),'ex',(select json_agg(i) from(select distinct announcement_id i from y where '갱신 할증'=cls order by 1 desc limit 4)q),'sent',(select count(*) from f where w),'sent_by_std',(select json_object_agg(std,n) from(select std,count(*)n from f where w group by 1)q),'any',(select count(*) from f where c or w),'any_by_std',(select json_object_agg(std,n) from(select std,count(*)n from f where c or w group by 1)q),'sent_not_cls',(select count(*) from f where w and not c),'cls_not_sent',(select count(*) from f where c and not w))j;
